  true,
  now(),
  '[
    {
        "q": "How far is Nekajui from Liberia Airport?",
        "a": "About 34 km (21 miles), a 35 to 45 minute private transfer on paved roads. It is at the far tip of Peninsula Papagayo, about 10 minutes beyond the Four Seasons."
    },
