  cover_image_alt_es = 'Arena blanca de concha de Playa Conchal frente al Westin, Guanacaste',
  faqs_es = '[
    {
        "q": "¿A qué distancia está el Westin Reserva Conchal del Aeropuerto de Liberia?",
